int OnInit() {
    g_config = new CXConfig(InpTargetMagics, InpTimerInterval, InpRemoteAddr);
    if(IS_INVALID(g_config)) return INIT_FAILED;

    // Set Timer in Milliseconds (0.3s -> 300ms)
    int timer_ms = (int)(g_config.GetTimerInterval() * 1000);
    if(timer_ms > 0) EventSetMillisecondTimer(timer_ms);
    else             EventSetTimer(1);

    // Create App Service
    g_app = new CXAppService(g_config);
    if(IS_INVALID(g_app)) return INIT_FAILED;

    // Two-phase initialization (Point 6 Fix)
    if(!g_app.Initialize(50)) {
        Print("[CRITICAL] CXAppService Initialization Failed (DB, Repo or Engine Error)");
        return INIT_FAILED;
    }

    return INIT_SUCCEEDED;
}

//+------------------------------------------------------------------+
