/**
 * @class CXDatabase
 * @brief 샌드박스화된 세션 전용 SQLite 핸들러
 */
class CXDatabase : public IDatabase {
private:
    int     m_db;
    string  m_db_path;

public:
    CXDatabase() : m_db(INVALID_HANDLE), m_db_path("XTX.db") {}
    virtual ~CXDatabase() { Close(); }

    virtual bool Open() override {
        //--- [Point 6 Fix] DATABASE_OPEN_CREATE 추가하여 최초 실행 시 DB 생성 보장
        m_db = DatabaseOpen(m_db_path, DATABASE_OPEN_READWRITE | DATABASE_OPEN_CREATE | DATABASE_OPEN_COMMON);
        if(m_db == INVALID_HANDLE) {
            PrintFormat("[DB-ERROR] Failed to open database: %s. Error: %d", m_db_path, _LastError);
            return false;
        }

        DatabaseExecute(m_db, "PRAGMA journal_mode=WAL;");
        DatabaseExecute(m_db, "PRAGMA synchronous=NORMAL;");

        //--- [필수] 신호 관리용 테이블 자동 생성
        string schema = "CREATE TABLE IF NOT EXISTS signals ("
                        "id INTEGER PRIMARY KEY AUTOINCREMENT,"
                        "sid TEXT UNIQUE,"
                        "gid TEXT,"
                        "symbol TEXT,"
                        "dir INTEGER,"
                        "type INTEGER,"
                        "lot REAL,"
                        "price_signal REAL,"
                        "price_open REAL,"
                        "price_close REAL,"
                        "tp REAL,"
                        "sl REAL,"
                        "te_start INTEGER,"
                        "te_step INTEGER,"
                        "ts_start INTEGER,"
                        "ts_step INTEGER,"
                        "xa_entry INTEGER,"
                        "xa_exit INTEGER,"
                        "xe_status INTEGER DEFAULT 0,"
                        "xe_status_msg TEXT,"
                        "ticket INTEGER DEFAULT 0,"
                        "magic INTEGER DEFAULT 0,"
                        "created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,"
                        "updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP"
                        ");";

        if(!DatabaseExecute(m_db, schema)) {
            PrintFormat("[DB-ERROR] Failed to create schema. Error: %d", _LastError);
            DatabaseClose(m_db);
            m_db = INVALID_HANDLE;
            return false;
        }

        return true;
    }

    virtual void Close() override {
        if(m_db != INVALID_HANDLE) {
            DatabaseClose(m_db);
            m_db = INVALID_HANDLE;
        }
    }

    virtual bool Execute(string sql) override {
        if(m_db == INVALID_HANDLE) return false;
        return DatabaseExecute(m_db, sql);
    }

    virtual int GetHandle() override { return m_db; }
};

#endif

