//--- Include core service
#include "App\CXAppService.mqh"
#include "Models\CXConfig.mqh"

//--- Input Parameters
input string InpTargetMagics = "1001,1002,3001,3002"; // Target Magic Numbers (CSV)
input double InpTimerInterval = 0.3;                 // Timer Interval (Seconds)
input string InpRemoteAddr   = "127.0.0.1:8787";      // Remote Log Address (IP:Port)

//--- Global Instance
CXAppService* g_app = NULL;
CXConfig*     g_config = NULL;

//+------------------------------------------------------------------+
//| Expert initialization function                                   |
//+------------------------------------------------------------------+
int OnInit() {
    g_config = new CXConfig(InpTargetMagics, InpTimerInterval, InpRemoteAddr);
    if(IS_INVALID(g_config)) return INIT_FAILED;

    // Set Timer in Milliseconds (0.3s -> 300ms)
    int timer_ms = (int)(g_config.GetTimerInterval() * 1000);
    if(timer_ms > 0) EventSetMillisecondTimer(timer_ms);
    else             EventSetTimer(1);

    // Create App Service
    g_app = new CXAppService(g_config);
    if(IS_INVALID(g_app)) return INIT_FAILED;

    // Two-phase initialization (Point 6 Fix)
    if(!g_app.Initialize(50)) {
        string msg = "CXAppService 초기화 실패!\n\n1. ATS.db 파일이 존재하는지 확인하십시오.\n2. ATSA(WPF 앱)가 먼저 실행되어 DB를 생성해야 합니다.";
        MessageBox(msg, "ATS [CRITICAL ERROR]", MB_OK | MB_ICONSTOP);
        return INIT_FAILED;
    }

    return INIT_SUCCEEDED;
}

//+------------------------------------------------------------------+
//| Expert deinitialization function                                 |
//+------------------------------------------------------------------+
void OnDeinit(const int reason) {
    EventKillTimer();
    SAFE_DELETE(g_app);
    SAFE_DELETE(g_config);
}

//+------------------------------------------------------------------+
//| Expert tick function                                             |
//+------------------------------------------------------------------+
void OnTick() {
    if(IS_VALID(g_app)) g_app.Pulse();
}

//+------------------------------------------------------------------+
//| Timer function                                                   |
//+------------------------------------------------------------------+
void OnTimer() {
    if(IS_VALID(g_app)) g_app.Pulse();
}

//+------------------------------------------------------------------+
//| TradeTransaction function                                        |
//+------------------------------------------------------------------+
void OnTradeTransaction(const MqlTradeTransaction& trans,
                        const MqlTradeRequest& request,
                        const MqlTradeResult& result) {
    if(IS_VALID(g_app)) g_app.OnTradeTransaction(trans, request, result);
}

