class CXStepEntry : public IXStep {
private:
    string m_name;

public:
    CXStepEntry() : m_name("Step_Entry") {}
    virtual ~CXStepEntry() {}

    virtual string Name() override { return m_name; }

    /**
     * @brief 진입 조건 확인 (xa_entry != XA_RAW && xa_status == XA_ACCEPTED)
     */
    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        ICXSignal* sig = xp.GetSignal();
        if(IS_INVALID(sig)) return false;

        // spec.md: Entry activation (xa_entry != XA_RAW AND xa_status == XA_ACCEPTED AND xe_status < XE_EXECUTED)
        return (sig.GetXAEntry() != XA_RAW && 
                sig.GetXAStatus() == XA_ACCEPTED && 
                sig.GetStatus() < XE_EXECUTED);
    }

    /**
     * @brief 진입 로직 실행
