if(node.step.OnCondition(xp, m_ctx, m_current_state)) {
    int next_state = node.step.OnProcess(xp, m_ctx);

    //-- [추가] Retries & OnFail 로직 구현
    if(next_state == m_current_state || next_state == -1) {
        // 상태 유지
        return;
    }

    // OnFail 경로 처리 (분기 맵에 정의된 실패 상태로의 이동인 경우)
    if(next_state == node.if_false && node.max_retries > 0) {
        node.current_retries++;
        if(node.current_retries <= node.max_retries) {
            XP_LOG_WARN(xp, StringFormat("[SEQ] Step '%s' failed. Retry %d/%d...", 
                node.step.Name(), node.current_retries, node.max_retries));
            return; // 현재 상태 유지하며 재시도 (OnCondition/OnProcess 다시 호출됨)
        } else {
            XP_LOG_ERROR(xp, StringFormat("[SEQ] Step '%s' exhausted retries. Moving to terminal fail state.", node.step.Name()));
            node.current_retries = 0; // 리셋
            UpdateState(node.if_false);
            return;
        }
    }

    int branch_state = -1;
    if(node.branches.TryGetValue(next_state, branch_state)) {
        node.current_retries = 0; // 성공 전이 시 리셋
        UpdateState(branch_state);
        return;
    }

    if(next_state != m_current_state && next_state != -1) {
        node.current_retries = 0; // 성공 전이 시 리셋
        UpdateState(next_state);
    }
}

