         DatabaseColumnDouble(req,  GetColumnIndex(req, "price_signal"), sig.price_signal);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "offset"),       sig.offset);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "step"),         sig.step);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "te_start"),     sig.te_start);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "te_step"),      sig.te_step);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "te_limit"),     sig.te_limit);
         DatabaseColumnInteger(req, GetColumnIndex(req, "te_interval"),  sig.te_interval);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "ikte_start"),    sig.ikte_start);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "ikte_step"),     sig.ikte_step);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "tp"),           sig.tp);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "sl"),           sig.sl);
         DatabaseColumnInteger(req, GetColumnIndex(req, "ts_start"),     sig.ts_start);
         DatabaseColumnInteger(req, GetColumnIndex(req, "ts_step"),      sig.ts_step);
         DatabaseColumnInteger(req, GetColumnIndex(req, "close_type"),   sig.close_type);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "trail_price"),  sig.trail_price);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "price_limit"),  sig.price_limit);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "price"),        sig.price);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "price_open"),   sig.price_open);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "price_close"),  sig.price_close);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "price_tp"),     sig.price_tp);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "price_sl"),     sig.price_sl);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "lot"),          sig.lot);
         DatabaseColumnLong(req,    GetColumnIndex(req, "ticket"),       sig.ticket);
         DatabaseColumnLong(req,    GetColumnIndex(req, "magic"),        sig.magic);
         DatabaseColumnText(req,    GetColumnIndex(req, "comment"),      sig.comment);
         DatabaseColumnText(req,    GetColumnIndex(req, "tag"),          sig.tag);

         string created_str;
         if(DatabaseColumnText(req, GetColumnIndex(req, "created"), created_str))
            sig.created = StringToTime(created_str);

         string updated_str;
         if(DatabaseColumnText(req, GetColumnIndex(req, "updated"), updated_str))
            sig.updated = StringToTime(updated_str);

         DatabaseColumnDouble(req,  GetColumnIndex(req, "limit_offset"), sig.limit_offset);
         DatabaseColumnDouble(req,  GetColumnIndex(req, "stop_offset"),  sig.stop_offset);

         list.Add(sig);
         count++;
      }
      return count;
   }
};

